mapper.sql:
WHERE is_approve=1 AND is_active=1
AND gld.company_id = #{filter.companyId}
AND vendor_id = #{filter.vendorId}
AND (SELECT branch_id FROM general_ledger_details WHERE general_ledger_id = gl.id LIMIT 1) = #{filter.branchId}
AND chart_account_id IN (SELECT id FROM chart_accounts WHERE is_active=1 AND chart_account_type_id IN (SELECT id FROM chart_account_types WHERE name='Accounts Payable')) AND sales_order_id IS NULL AND credit_memo_id IS NULL AND purchase_order_id IS NULL AND purchase_return_id IS NULL AND gl.landed_cost_id IS NULL AND (credit-(IFNULL((SELECT IFNULL(SUM(debit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND company_id = gld.company_id AND vendor_id = gld.vendor_id), 0)))>0.001 AND credit>0

mapper.select:
SELECT



ORDER BY ap_agings.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT file_name AS fileName, file_url AS fileUrl FROM general_ledger_files WHERE general_ledger_id IN (
    SELECT id FROM general_ledgers WHERE ap_aging_id = #{glId}
    );

SELECT IFNULL(SUM(debit),0) AS debit, `main_gl_id` AS mainGlId, `chart_account_id` AS chartAccountId, `company_id` AS companyId, `vendor_id` AS vendorId FROM general_ledgers gl2 INNER JOIN general_ledger_details gld2 ON gl2.id=gld2.general_ledger_id WHERE gl2.is_approve=1 AND gl2.is_active=1
AND company_id = #{filter.companyId}
AND vendor_id = #{filter.vendorId}
AND chart_account_id IN (SELECT id FROM chart_accounts WHERE is_active=1 AND chart_account_type_id IN (SELECT id FROM chart_account_types WHERE name='Accounts Payable')) AND sales_order_id IS NULL AND credit_memo_id IS NULL AND purchase_order_id IS NULL AND purchase_return_id IS NULL AND debit > 0 GROUP BY `main_gl_id`, `chart_account_id`, `company_id`, `vendor_id`
